insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('45f2ae71-95ca-4f20-9dff-64dc0fe14981', 'situacion', 'QUÍMICA', 'ctx-sit', '<p>En la tabla se presentan características físicas y químicas de 4 sustancias puras.</p><table class="ctx-table"><tr><th>Sustancia</th><th>Punto de ebullición (°C)</th><th>Punto de fusión (°C)</th><th>Conductividad eléctrica (S/m)</th><th>Presión de vapor (Pa)</th></tr><tr><td>X</td><td>100,0</td><td>0</td><td>0,00005</td><td>3066,4</td></tr><tr><td>Y</td><td>64,7</td><td>−97</td><td>4 × 10<sup>−19</sup></td><td>13020,0</td></tr><tr><td>Z</td><td>78,4</td><td>−114</td><td>0,00006</td><td>5950,0</td></tr><tr><td>W</td><td>97,5</td><td>−126</td><td>6 × 10<sup>−18</sup></td><td>1990,0</td></tr></table>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('4f62cd55-b506-4ba9-9ad0-8794eee69230', 'situacion', 'QUÍMICA', 'ctx-sit', '<p>Un puente de hidrógeno se forma, entre otros, por la interacción entre el átomo de hidrógeno unido al oxígeno en una molécula de alcohol y un átomo de oxígeno de otra molécula de alcohol (ver figura 1), lo que aumenta su punto de ebullición. Sin embargo, los puentes de hidrógeno de una molécula de alcohol son más débiles a medida que aumenta la cantidad de carbono en su estructura.</p><figure class="ctx-fig"><img src="img/figuras/qui/q5-q78-estructuras.webp" loading="lazy" alt="Tres fórmulas estructurales. Figura 1: dos moléculas unidas por un puente de hidrógeno punteado entre el hidrógeno de una y el oxígeno de la otra. Figura 2, etilenglicol: dos carbonos en cadena, cada uno con un grupo OH. Figura 3, propanol: tres carbonos en cadena con un solo grupo OH en un extremo."></figure>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('cccbec59-4438-4781-b79e-92f3bbcce9fa', 'situacion', 'QUÍMICA', 'ctx-sit', '<p>A continuación se presentan los modelos atómicos de tres átomos (I, II y III) de un mismo elemento, donde se muestra el número de electrones, protones y neutrones.</p><figure class="ctx-fig"><img src="img/figuras/qui/q5-q79-atomos.webp" loading="lazy" alt="Tres modelos atómicos. En los tres hay un electrón girando alrededor del núcleo. El átomo I tiene un protón en el núcleo; el II, un protón y un neutrón; el III, un protón y dos neutrones."></figure>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('0a1c9ad3-7fd8-4407-9db0-d0a477249a08', 'situacion', 'QUÍMICA', 'ctx-sit', '<p>En la tabla se muestra la configuración electrónica de un átomo y de un ion de aluminio.</p><table class="ctx-table"><tr><th></th><th>Aluminio neutro</th><th>Ion de aluminio</th></tr><tr><td>Configuración electrónica</td><td>1s<sup>2</sup>2s<sup>2</sup>2p<sup>6</sup>3s<sup>2</sup>3p<sup>1</sup></td><td>1s<sup>2</sup>2s<sup>2</sup>2p<sup>6</sup></td></tr></table>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('5578b996-c19c-4191-9e2c-73afd749a325', 'situacion', 'QUÍMICA', 'ctx-sit', '<p>Cuatro estudiantes quieren saber si la tinta púrpura está conformada por varios colores que fueron mezclados.</p><p>Ellos tienen la hipótesis de que tanto el etanol como el agua son disolventes que podrán separar la mezcla de tinta. Para evaluarla toman una gota de la tinta y separan los colores que la componen usando ambos disolventes, y descubren que la tinta púrpura está compuesta de los colores rojo y azul. Finalmente, con estos resultados concluyen que tanto el agua como el etanol separan la mezcla de tinta en sus dos colores: rojo y azul.</p><p>Cada uno de los estudiantes decide elaborar una cartelera para resumir las conclusiones de la investigación.</p>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('505feac3-5a6e-4193-9b5d-3aa5876e18e7', 'situacion', 'QUÍMICA', 'ctx-sit', '<p>A continuación se presentan dos unidades mediante las cuales se puede medir la concentración de una disolución:</p><p style="font-family:var(--font-mono);text-align:center">% p/V = masa de sustancia (g) ÷ 100 mL de disolución × 100 %</p><p style="font-family:var(--font-mono);text-align:center">M = masa de sustancia (mol) ÷ 1 L de disolución &nbsp;&nbsp; (1 L = 1000 mL)</p><p>Un estudiante tiene dos disoluciones de distinta concentración de una misma sustancia, cuya masa es 200 g por cada mol, como se muestra a continuación.</p><figure class="ctx-fig"><img src="img/figuras/qui/q5-q82-disoluciones.webp" loading="lazy" alt="Dos recipientes graduados iguales, marcados de 50 a 200 mililitros. La disolución 1 tiene volumen 100 mililitros y concentración 20 %; la disolución 2, volumen 100 mililitros y concentración 1 molar."></figure>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('b459b00f-9fdc-4822-9644-9d5dc73836c7', 'situacion', 'QUÍMICA', 'ctx-sit', '<p>En la tabla se muestran las variaciones de presión de una cantidad fija de un gas en un recipiente cerrado, variando la temperatura, pero manteniendo las demás condiciones sin variar.</p><table class="ctx-table"><tr><th>Temperatura (K)</th><th>Presión (atm)</th></tr><tr><td>298</td><td>1</td></tr><tr><td>323</td><td>2</td></tr><tr><td>373</td><td>4</td></tr></table><p>Un estudiante quiere explicar este comportamiento y recurre a la ley de los gases ideales:</p><p style="font-family:var(--font-mono);text-align:center">P V = n R T</p><p>Donde P es la presión, V el volumen, n el número de moles, R la constante de los gases ideales y T la temperatura.</p>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('53427e88-6a2a-4e1c-84d1-acb5499dd6a5', 'situacion', 'QUÍMICA', 'ctx-sit', '<p>Se tiene una mezcla de dos líquidos no solubles entre sí (agua y aceite) y partículas sólidas de hierro metálico (limadura de hierro). El hierro es un metal ferromagnético que es atraído por el campo magnético de los imanes. Para separar los componentes de la mezcla se cuenta con los métodos de separación que se muestran en la tabla.</p><table class="ctx-table"><tr><th>Método</th><th>Descripción</th></tr><tr><td>Filtración</td><td>Separa sólidos insolubles de líquidos.</td></tr><tr><td>Decantación</td><td>Separa líquidos que no se solubilizan entre sí y tienen diferentes densidades.</td></tr><tr><td>Sublimación</td><td>Separa mezclas de sólidos donde uno de ellos pasa de sólido a gas, sin pasar por el estado líquido.</td></tr><tr><td>Separación magnética</td><td>Separa los componentes que son atraídos por imanes de una mezcla.</td></tr></table>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('ab18004f-0a7c-48c2-a95b-a12ece569522', 'situacion', 'QUÍMICA', 'ctx-sit', '<p>A continuación se muestran 3 pasos que describen la reacción que ocurre entre KI y Ag+, y el filtrado del AgI que resultó como producto.</p><figure class="ctx-fig"><img src="img/figuras/qui/q5-q85-agi.webp" loading="lazy" alt="Tres pasos. Uno: se vierte KI sobre un recipiente con iones Ag+. Dos: la mezcla contiene ya AgI. Tres: el AgI, filtrado, queda como un sólido sobre la superficie."></figure>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('8ca2a26e-9601-40d1-86b6-bb6fa2331b68', 'situacion', 'QUÍMICA', 'ctx-sit', '<p>Juan considera que algunas de las sustancias que consumimos son más ácidas que otras, por eso él tiene la hipótesis de que entre el jugo de naranja, el café y la leche, el pH del jugo de naranja es el menor y el de la leche es el mayor.</p>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('28f6fc35-4cdf-459d-b71d-2b9f92f1534f', 'situacion', 'QUÍMICA', 'ctx-sit', '<p>Un ion es una especie química que ha ganado o perdido electrones y por lo tanto tiene carga. La configuración electrónica para un átomo neutro «P» con Z = 19 es 1s<sup>2</sup> 2s<sup>2</sup> 2p<sup>6</sup> 3s<sup>2</sup> 3p<sup>6</sup> 4s<sup>1</sup>.</p>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('856fe8fc-7bfd-442c-bd47-816104947b58', 'situacion', 'QUÍMICA', 'ctx-sit', '<p>Un estudiante tiene la hipótesis de que un tipo de dulces se disuelve completamente en el mismo tiempo en alcohol, agua y aceite. Para comprobarlo, coloca dulces idénticos, del mismo tamaño, y los sumerge en las tres sustancias. Al transcurrir el mismo tiempo para las tres sustancias obtiene los resultados que se muestran en la tabla.</p><table class="ctx-table"><tr><th>Sustancia</th><th>Observación</th></tr><tr><td>Alcohol</td><td>Se disuelve un poco</td></tr><tr><td>Agua</td><td>Se disuelve completamente</td></tr><tr><td>Aceite</td><td>No se disuelve</td></tr></table>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('d25b0179-8817-4b93-a1d9-7a380257375f', 'situacion', 'QUÍMICA', 'ctx-sit', '<p>El CO<sub>2</sub>, gas carbónico, en condiciones de presión y temperatura adecuada se puede encontrar en estado sólido y es llamado hielo seco, y es usado frecuentemente como refrigerante. Tiene ventajas como la de refrigerar a menor temperatura que la del hielo y que pasa de estado sólido a gaseoso sin pasar por el estado líquido, lo cual evita deterioros de las sustancias refrigeradas. El dióxido de carbono, CO<sub>2</sub>, en estado líquido se usa en la fabricación de bebidas carbonatadas (bebidas gaseosas) y en extintores.</p><p>En el siguiente diagrama de fases se indica los cambios de estado de la materia teniendo en cuenta los cambios en las condiciones de presión y temperatura.</p><figure class="ctx-fig"><img src="img/figuras/qui/q5-q89-fases.webp" loading="lazy" alt="Diagrama con tres estados en triángulo. De sólido a líquido, fusión; de líquido a sólido, solidificación. De sólido a gas, sublimación; de gas a sólido, sublimación inversa. De líquido a gas, vaporización o ebullición; de gas a líquido, condensación o licuefacción."></figure><figure class="ctx-fig"><img src="img/figuras/qui/q5-q89-pt.webp" loading="lazy" alt="Gráfica de presión contra temperatura con las regiones sólido arriba a la izquierda, líquido en el centro y gas a la derecha, separadas por dos curvas. Sobre ella hay cuatro flechas numeradas: la 1 apunta hacia la derecha dentro de la región del gas; la 2 sube hacia la izquierda cruzando primero la curva que separa gas de líquido y después la que separa líquido de sólido; la 3 apunta hacia la izquierda por la parte baja de la gráfica; y la 4 apunta hacia abajo."></figure>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('6c4fbab5-3323-4b88-918f-1ae6a33ce273', 'situacion', 'QUÍMICA', 'ctx-sit', '<p>El CO<sub>2</sub>, gas carbónico, en condiciones de presión y temperatura adecuada se puede encontrar en estado sólido y es llamado hielo seco, y es usado frecuentemente como refrigerante. Tiene ventajas como la de refrigerar a menor temperatura que la del hielo y que pasa de estado sólido a gaseoso sin pasar por el estado líquido, lo cual evita deterioros de las sustancias refrigeradas. El dióxido de carbono, CO<sub>2</sub>, en estado líquido se usa en la fabricación de bebidas carbonatadas (bebidas gaseosas) y en extintores.</p><p>En el siguiente diagrama de fases se indica los cambios de estado de la materia teniendo en cuenta los cambios en las condiciones de presión y temperatura.</p><figure class="ctx-fig"><img src="img/figuras/qui/q5-q89-fases.webp" loading="lazy" alt="Diagrama con tres estados en triángulo. De sólido a líquido, fusión; de líquido a sólido, solidificación. De sólido a gas, sublimación; de gas a sólido, sublimación inversa. De líquido a gas, vaporización o ebullición; de gas a líquido, condensación o licuefacción."></figure>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('51014855-c888-46aa-9aa8-8fd7abb0beac', 'situacion', 'QUÍMICA', 'ctx-sit', '<p>La contaminación ambiental es la incorporación de sustancias sólidas, líquidas o gaseosas, o mezclas de ellas, a medios receptores que alteran desfavorablemente las condiciones naturales del mismo, o que puedan afectar la salud, la higiene o el bienestar del público. Los medios que reciben los contaminantes son el agua, el aire y el suelo. En la actualidad existen varios métodos de descontaminación de cuerpos de agua, aire y suelo.</p><p>Se tomaron cuatro (4) muestras de agua contaminada de diferentes lugares. Mediante un análisis, se determinó la cantidad de plomo presente en cada muestra, los resultados se muestran en la tabla.</p><table class="ctx-table"><tr><th>Muestra</th><th>Masa de plomo (mg)</th><th>Volumen de muestra (L)</th></tr><tr><td>1</td><td>2,5</td><td>50</td></tr><tr><td>2</td><td>5,0</td><td>100</td></tr><tr><td>3</td><td>15,0</td><td>200</td></tr><tr><td>4</td><td>50,0</td><td>1.000</td></tr></table>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('ed85a062-e049-464a-a216-dcd6185e0adb', 'situacion', 'QUÍMICA', 'ctx-sit', '<p>Una muestra de agua contaminada presenta entre sus componentes el elemento X. Este elemento se oxida en presencia de agua y oxígeno. Algunas de las reacciones que el elemento X presenta frente a diferentes sustancias se muestran en las ecuaciones 1, 2 y 3.</p><p style="font-family:var(--font-mono);text-align:center">1. &nbsp; 2X + O<sub>2</sub> → 2XO</p><p style="font-family:var(--font-mono);text-align:center">2. &nbsp; XO + H<sub>2</sub>O → X(OH)<sub>2</sub></p><p style="font-family:var(--font-mono);text-align:center">3. &nbsp; X(OH)<sub>2</sub> + Z → D + H<sub>2</sub>O</p><p>Al medir el pH del producto de la reacción 2 se encuentra un valor mayor que 7.</p>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('17e15e4b-1a45-4de7-9162-6bc1c3591bad', 'situacion', 'QUÍMICA', 'ctx-sit', '<p>A continuación se ilustran cuatro métodos de separación de mezclas.</p><figure class="ctx-fig"><img src="img/figuras/qui/q5-q93-metodos.webp" loading="lazy" alt="Cuatro montajes: magnetismo, que es el método 1; tamizado, el método 3; filtración, el método 2; y decantación, el método 4."></figure><p>Se emplearon algunos materiales, identificados con las letras K, L, H, F, para preparar cuatro mezclas de diferente composición. Posteriormente, cada una de ellas fue separada por el método más apropiado, obteniéndose los siguientes resultados:</p><table class="ctx-table"><tr><th>Componente separado</th><th>Método(s) empleado(s)</th><th>Característica de la sustancia</th></tr><tr><td>K</td><td>2 y 4</td><td>Agua. Densidad = 1 g/cm<sup>3</sup></td></tr><tr><td>F</td><td>2, 1 y 3</td><td>Polvo insoluble en agua.</td></tr><tr><td>H</td><td>1</td><td>Trozos con propiedades magnéticas.</td></tr><tr><td>L</td><td>4</td><td>Líquido insoluble en agua. Densidad = 0,6 g/cm<sup>3</sup></td></tr></table>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('11e80ef1-4c72-4515-9033-a67d219bb351', 'situacion', 'QUÍMICA', 'ctx-sit', '<p>Se tiene una mezcla líquida de 3 compuestos X, Y y Z solubles entre sí. Para recolectar cada líquido por separado, se ha decidido tener en cuenta el punto de ebullición de cada uno a 1 atm de presión.</p><table class="ctx-table"><tr><th>Líquido</th><th>X</th><th>Y</th><th>Z</th></tr><tr><td>Punto de ebullición (°C)</td><td>40</td><td>53,1</td><td>82,3</td></tr></table><p>En el laboratorio hay disponibles cuatro montajes.</p><figure class="ctx-fig"><img src="img/figuras/qui/q5-q95-montajes.webp" loading="lazy" alt="Cuatro montajes de laboratorio. Filtración: un embudo con papel de filtro sobre un recipiente, que retiene el sólido y deja pasar el líquido. Evaporación: un recipiente ancho calentado con mechero hasta que el líquido se va y queda el sólido. Destilación: un balón con termómetro sobre un mechero, unido a un refrigerante inclinado que recoge aparte el líquido condensado. Decantación: un embudo donde un líquido queda encima del otro y se deja salir el de abajo por la llave."></figure>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('7a7c4d09-f324-4824-bbc7-5a1fd6ef2db2', 'situacion', 'QUÍMICA', 'ctx-sit', '<p>A continuación se muestran las fórmulas estructurales de las sustancias R, J y T.</p><figure class="ctx-fig"><img src="img/figuras/qui/q5-q96-estructuras.webp" loading="lazy" alt="Tres fórmulas. R: dos carbonos unidos por doble enlace, cada uno con dos hidrógenos. J: tres átomos de oxígeno unidos entre sí. T: un carbono unido por dobles enlaces a dos oxígenos."></figure>');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '88deb86d-e752-4076-a4f5-f8ede3396e7b', 'qui',
  (select id from public.temas where materia = 'qui' and codigo = 'clasificacion-de-la-materia'),
  (select id from public.lotes where codigo = '2026-B'),
  '45f2ae71-95ca-4f20-9dff-64dc0fe14981', 'Materia: clasificación y propiedades',
  'Según la información de la tabla, se puede observar que las sustancias Y y Z tienen como característica común que',
  array['presentan la misma composición química.', 'presentan una presión de vapor superior a 4000 Pa.', 'tienen valores de conductividad eléctrica superiores a 0,00001 S/m.', 'tienen puntos de fusión más altos que los de ebullición.'],
  'Recorre la tabla columna por columna y descarta en cuanto una de las dos sustancias no cumpla.', 'publicada', 'modelo', 'dc13fa792cc7335650006233dcfd707d', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('88deb86d-e752-4076-a4f5-f8ede3396e7b', 1, 'Hay que buscar la única columna donde Y y Z coinciden. En presión de vapor marcan 13020 y 5950, las dos por encima de 4000. En conductividad no: Z tiene 0,00006, que sí supera 0,00001, pero Y tiene 4 por 10 elevado a menos 19, un número muchísimo más pequeño. Y sus puntos de fusión, −97 y −114, están muy por debajo de sus puntos de ebullición, no por encima. Que tuvieran la misma composición química es imposible: si lo fueran, todas sus propiedades coincidirían.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '73394b16-9ed2-40e0-a388-0619a7fd4a65', 'qui',
  (select id from public.temas where materia = 'qui' and codigo = 'quimica-organica'),
  (select id from public.lotes where codigo = '2026-B'),
  '4f62cd55-b506-4ba9-9ad0-8794eee69230', 'Orgánica',
  'Teniendo en cuenta lo anterior, ¿cuál de las estructuras de las figuras 2 y 3 presentará mayor punto de ebullición?',
  array['El propanol, porque tiene mayor número de carbonos, lo cual modifica el número de puentes de hidrógeno.', 'El propanol, porque tiene menor número de oxígenos, lo cual disminuye el número de puentes de hidrógeno.', 'El etilenglicol, porque tiene mayor número de oxígenos, lo cual disminuye el número de puentes de hidrógeno.', 'El etilenglicol, porque tiene mayor número de carbonos, lo cual aumenta el número de puentes de hidrógeno.'],
  'Cuenta los grupos OH de cada estructura: cada uno es una posibilidad más de formar puente de hidrógeno.', 'publicada', 'modelo', 'b9d274dfd215969ea11e17397b79fe43', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('73394b16-9ed2-40e0-a388-0619a7fd4a65', 2, 'El etilenglicol tiene dos grupos OH y el propanol solo uno, así que el etilenglicol puede formar más puentes de hidrógeno y por eso hierve a mayor temperatura. Además el enunciado avisa de que los puentes se debilitan cuando crece la cadena de carbonos, y el propanol tiene tres carbonos frente a los dos del etilenglicol: las dos razones apuntan al mismo lado. La opción que nombra el etilenglicol por sus carbonos se equivoca de dato, porque es el que menos tiene.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '9d6f5323-d46f-4f99-8342-37aa0be23671', 'qui',
  (select id from public.temas where materia = 'qui' and codigo = 'estructura-de-la-materia'),
  (select id from public.lotes where codigo = '2026-B'),
  'cccbec59-4438-4781-b79e-92f3bbcce9fa', 'Teoría atómica',
  'Teniendo en cuenta la información anterior, ¿cuál de las siguientes afirmaciones es válida acerca de las estructuras de los anteriores átomos?',
  array['El átomo I tiene más electrones que el átomo III.', 'Los tres átomos tienen el mismo número de neutrones.', 'El átomo II tiene más electrones que el átomo III.', 'Los tres átomos tienen el mismo número de protones.'],
  'Recuerda qué partícula define de qué elemento se trata. Esa es la que no puede cambiar entre los tres.', 'publicada', 'modelo', 'f096599eb136d2d2148511d0659aa2a6', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('9d6f5323-d46f-4f99-8342-37aa0be23671', 3, 'El enunciado dice que son átomos del mismo elemento, y lo que define a un elemento es su número de protones: si cambiara, ya sería otro elemento. En los tres dibujos hay un solo protón. Los electrones también son uno en cada uno, así que ninguno tiene más que otro. Lo que sí cambia de un dibujo al siguiente es la cantidad de neutrones, que va de cero a dos: por eso son isótopos.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '80f1c586-5c72-4804-acc7-5e66cfd8ef59', 'qui',
  (select id from public.temas where materia = 'qui' and codigo = 'estructura-de-la-materia'),
  (select id from public.lotes where codigo = '2026-B'),
  '0a1c9ad3-7fd8-4407-9db0-d0a477249a08', 'Teoría atómica',
  'Teniendo en cuenta que el estado de oxidación de un átomo se determina conociendo los cambios en el número de electrones de la configuración electrónica respecto al átomo neutro, se puede afirmar que el estado de oxidación del ion de aluminio es de 3+, porque',
  array['el último nivel de energía de su configuración electrónica es 3.', 'tiene 3 electrones menos en su configuración electrónica que el aluminio.', 'tiene 3 electrones más en su configuración electrónica que el aluminio.', 'el número total de electrones en su configuración electrónica es 3.'],
  'Suma los electrones de cada configuración y resta. El signo lo da si perdió o ganó.', 'publicada', 'modelo', '06c7fb0d272ca5b70c00308511ddd16a', 'alta';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('80f1c586-5c72-4804-acc7-5e66cfd8ef59', 1, 'Basta con sumar los superíndices de cada fila. El aluminio neutro tiene 2 más 2 más 6 más 2 más 1, que son 13 electrones; el ion tiene 2 más 2 más 6, que son 10. Perdió tres electrones, y perder carga negativa deja al átomo con tres cargas positivas de más: por eso el 3+. Si hubiera ganado electrones la carga sería negativa, y los 10 electrones que le quedan no son 3.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select 'c7083a6d-1209-4507-a1fe-fc443385f500', 'qui',
  (select id from public.temas where materia = 'qui' and codigo = 'indagacion-experimental'),
  (select id from public.lotes where codigo = '2026-B'),
  '5578b996-c19c-4191-9e2c-73afd749a325', 'Indagación experimental',
  '¿Cuál de las siguientes carteleras presenta adecuadamente las conclusiones de la investigación?',
  array['<b>Conclusiones del estudiante 1</b><ul><li>Agregar una gota de tinta púrpura en etanol.</li><li>Agregar una gota de tinta púrpura en agua.</li></ul>', '<b>Conclusiones del estudiante 2</b><ul><li>El agua y el etanol son apropiados para separar los colores de la tinta púrpura.</li><li>La tinta púrpura está compuesta por los colores rojo y azul.</li></ul>', '<b>Conclusiones del estudiante 3</b><ul><li>La tinta púrpura está compuesta por más colores que la tinta azul y rosada.</li><li>Las tintas púrpura y roja pueden usarse en esferos.</li></ul>', '<b>Conclusiones del estudiante 4</b><ul><li>El etanol puede separar los colores que componen la tinta púrpura, pero el agua no puede hacer esta separación.</li><li>Una gota de tinta púrpura está compuesta de etanol y agua.</li></ul>'],
  'Separa tres cosas: lo que se hizo, lo que se vio y lo que se concluye. Solo lo tercero puede ir en una cartelera de conclusiones.', 'publicada', 'modelo', 'ff3fbcba53351d5954adbb42085e749e', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('c7083a6d-1209-4507-a1fe-fc443385f500', 1, 'Una conclusión responde a lo que se preguntó usando lo que se observó. Aquí se preguntó si la tinta es una mezcla y si los dos disolventes sirven, y se vio que sí en ambos casos: esa es la cartelera correcta. Otra de ellas enumera lo que se hizo, que es el procedimiento y no una conclusión. Otra habla de tintas que nunca se probaron y de para qué sirven, cosas que el experimento no midió. Y la última afirma que el agua no sirvió, justo lo contrario de lo observado.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '30148600-d3a3-45e5-98cc-b7e17d96dba6', 'qui',
  (select id from public.temas where materia = 'qui' and codigo = 'soluciones'),
  (select id from public.lotes where codigo = '2026-B'),
  '505feac3-5a6e-4193-9b5d-3aa5876e18e7', 'Soluciones',
  'Teniendo en cuenta la masa de un mol de la sustancia, ¿son equivalentes las concentraciones de ambas disoluciones?',
  array['Sí, porque las dos disoluciones tienen un volumen diferente.', 'Sí, porque de acuerdo con el valor de la masa, 1 mol/L equivale a 200 g/1000 mL, que sería igual a 20 % p/V.', 'No, porque la cantidad de moles son las mismas en las dos disoluciones, de manera que la concentración no cambia.', 'No, porque las disoluciones están preparadas con la misma sustancia.'],
  'Convierte la concentración molar a gramos por cada 100 mL y compárala con el porcentaje.', 'publicada', 'modelo', '100e265af61741fe042f4d97f530d077', 'alta';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('30148600-d3a3-45e5-98cc-b7e17d96dba6', 1, 'Hay que llevar las dos concentraciones a la misma unidad. Un molar significa un mol por litro, y como cada mol pesa 200 gramos, eso son 200 gramos en 1000 mililitros. Reduciendo a la décima parte: 20 gramos en 100 mililitros, que es exactamente lo que significa 20 % peso-volumen. Así que sí son equivalentes. Y no por las razones de las otras opciones: los dos volúmenes son iguales, 100 mililitros, y usar la misma sustancia no dice nada sobre la concentración.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select 'dc0f72fa-8ecd-4703-bdd0-b0319dcd2c82', 'qui',
  (select id from public.temas where materia = 'qui' and codigo = 'gases'),
  (select id from public.lotes where codigo = '2026-B'),
  'b459b00f-9fdc-4822-9644-9d5dc73836c7', 'Gases',
  'Con base en la información anterior, y teniendo en cuenta la ley de los gases ideales, ¿cómo cambia el comportamiento del gas cuando aumenta la temperatura en el recipiente?',
  array['Aumenta el número de moles del gas.', 'Disminuye el volumen del gas.', 'Aumenta la presión del gas.', 'Disminuye la densidad del gas.'],
  'Marca en la fórmula qué se mantiene fijo por el enunciado. Lo que queda es lo único que puede moverse.', 'publicada', 'modelo', 'f56141520c41dbe71d16ae94fae2bf30', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('dc0f72fa-8ecd-4703-bdd0-b0319dcd2c82', 2, 'La tabla misma lo enseña: al pasar de 298 a 373 kelvin la presión sube de 1 a 4 atmósferas. Y la fórmula lo explica: el recipiente es cerrado y rígido, así que el volumen no cambia, y la cantidad de gas tampoco, porque no entra ni sale nada. Con el volumen y los moles fijos, si sube la temperatura del lado derecho tiene que subir la presión del izquierdo. La densidad es masa sobre volumen, y ninguna de las dos cambió.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '9db1f891-e4f4-474c-ae75-e93794a3c3b5', 'qui',
  (select id from public.temas where materia = 'qui' and codigo = 'clasificacion-de-la-materia'),
  (select id from public.lotes where codigo = '2026-B'),
  '53427e88-6a2a-4e1c-84d1-acb5499dd6a5', 'Materia: clasificación y propiedades',
  'Con base en la información anterior, ¿cuáles métodos específicos son los más adecuados para obtener por separado el agua, el hierro y el aceite?',
  array['Separación magnética y decantación.', 'Filtración y separación magnética.', 'Filtración y sublimación.', 'Separación magnética y sublimación.'],
  'Trata cada componente por separado y busca en la tabla el método que aprovecha justo su propiedad.', 'publicada', 'modelo', 'be0c8e21078766fec2332d5bd8060f0d', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('9db1f891-e4f4-474c-ae75-e93794a3c3b5', 0, 'Son dos problemas distintos. El hierro es un sólido que el imán atrae, así que sale con separación magnética; la filtración también lo sacaría, pero desaprovecha la propiedad que el enunciado se molesta en mencionar. Lo que queda son dos líquidos que no se mezclan y tienen densidades distintas, y para eso está la decantación: el aceite queda arriba y el agua abajo. La sublimación no sirve porque ninguno de los tres pasa de sólido a gas.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select 'dfc538d7-48e2-4a94-9743-5e173927c3a9', 'qui',
  (select id from public.temas where materia = 'qui' and codigo = 'reacciones-estequiometria'),
  (select id from public.lotes where codigo = '2026-B'),
  'ab18004f-0a7c-48c2-a95b-a12ece569522', 'Reacciones químicas',
  'En el paso 3, el producto AgI es un compuesto porque',
  array['es una nueva sustancia constituida por dos átomos diferentes de la tabla periódica.', 'siempre que se mezclen dos sustancias sólidas se formará un compuesto.', 'todas las sustancias sólidas que se encuentran en la naturaleza son compuestos.', 'presenta un solo elemento de la tabla periódica en su estructura química.'],
  'Repasa la definición de compuesto y comprueba cuántos elementos distintos hay en la fórmula.', 'publicada', 'modelo', 'e7a0d3200f70cc20f4f0e0bbac2d0daf', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('dfc538d7-48e2-4a94-9743-5e173927c3a9', 0, 'Un compuesto es una sustancia formada por átomos de elementos distintos unidos químicamente. El AgI cumple: tiene plata y yodo, dos elementos diferentes, unidos en una sustancia nueva que no es ninguno de los dos de partida. Tener un solo elemento sería justo lo contrario, eso sería una sustancia simple. Y ni mezclar dos sólidos produce siempre un compuesto —muchas mezclas se quedan en mezclas— ni todo sólido natural es un compuesto: el oro y el azufre, por ejemplo, no lo son.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '34ead252-373f-4543-b603-750647c844cc', 'qui',
  (select id from public.temas where materia = 'qui' and codigo = 'acidos-y-bases'),
  (select id from public.lotes where codigo = '2026-B'),
  '8ca2a26e-9601-40d1-86b6-bb6fa2331b68', 'Ácidos, bases y pH',
  'Si la hipótesis de Juan es verdadera, ¿cuál de las siguientes gráficas representa los resultados esperados?',
  array['<figure class="ctx-fig"><img src="img/figuras/qui/q5-q86-a.webp" loading="lazy" alt="Gráfica de barras de pH: el jugo de naranja es la barra más alta, el café la más baja y la leche queda en un valor intermedio."></figure>', '<figure class="ctx-fig"><img src="img/figuras/qui/q5-q86-b.webp" loading="lazy" alt="Gráfica de barras de pH: el jugo de naranja queda en un valor intermedio, el café es la barra más baja y la leche la más alta."></figure>', '<figure class="ctx-fig"><img src="img/figuras/qui/q5-q86-c.webp" loading="lazy" alt="Gráfica de barras de pH: el jugo de naranja es la barra más baja, el café queda en medio y la leche es la más alta."></figure>', '<figure class="ctx-fig"><img src="img/figuras/qui/q5-q86-d.webp" loading="lazy" alt="Gráfica de barras de pH: el jugo de naranja es la barra más alta, el café queda en medio y la leche es la más baja."></figure>'],
  'Traduce la hipótesis a un orden entre las tres barras y busca la gráfica que lo respeta de punta a punta.', 'publicada', 'modelo', '8c3cf73b9ea0b02a36754c4ae0efc789', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('34ead252-373f-4543-b603-750647c844cc', 2, 'La hipótesis fija los dos extremos: el jugo de naranja abajo y la leche arriba. Eso obliga a que las tres barras crezcan en ese orden, de izquierda a derecha, quedando el café en medio. Solo una de las gráficas lo hace. Dos de ellas ponen el jugo de naranja como la barra más alta, que es exactamente lo contrario de lo que dice la hipótesis, y otra deja la leche por debajo del jugo.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select 'b71f455e-7771-4827-9692-6bc8f777cf1b', 'qui',
  (select id from public.temas where materia = 'qui' and codigo = 'estructura-de-la-materia'),
  (select id from public.lotes where codigo = '2026-B'),
  '28f6fc35-4cdf-459d-b71d-2b9f92f1534f', 'Teoría atómica',
  'De acuerdo con esto, la configuración electrónica más probable para el ion P<sup>+1</sup> es',
  array['1s<sup>2</sup> 2s<sup>2</sup> 2p<sup>6</sup> 3s<sup>2</sup> 3p<sup>6</sup> 4s<sup>2</sup>', '1s<sup>2</sup> 2s<sup>2</sup> 2p<sup>6</sup> 3s<sup>2</sup> 3p<sup>6</sup>', '1s<sup>2</sup> 2s<sup>2</sup> 2p<sup>6</sup> 3s<sup>2</sup> 3p<sup>5</sup>', '1s<sup>2</sup> 2s<sup>2</sup> 2p<sup>6</sup> 3s<sup>2</sup> 3p<sup>6</sup> 3d<sup>1</sup>'],
  'Carga positiva es electrones perdidos. Quita el del nivel de energía más alto, no el último que escribiste.', 'publicada', 'modelo', '55e472b24bf4f8e42ef39e63ae0a3a4b', 'alta';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('b71f455e-7771-4827-9692-6bc8f777cf1b', 1, 'La carga +1 significa que el átomo perdió un electrón, así que hay que quitar uno de los 19. Y no se quita de cualquier sitio: sale el del nivel más externo, que aquí es el único electrón del 4s. Al irse, ese subnivel desaparece de la configuración y queda terminando en 3p6, con 18 electrones. Quitar el electrón del 3p sería sacarlo de un nivel más interno, y las otras dos opciones añaden electrones en vez de quitarlos.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select 'ade731f1-e116-4aa5-95f6-16d7257b5459', 'qui',
  (select id from public.temas where materia = 'qui' and codigo = 'indagacion-experimental'),
  (select id from public.lotes where codigo = '2026-B'),
  '856fe8fc-7bfd-442c-bd47-816104947b58', 'Indagación experimental',
  'De acuerdo con lo anterior, se puede afirmar que la hipótesis planteada por el estudiante es',
  array['verdadera, porque el dulce se disuelve completamente en las tres sustancias empleadas.', 'falsa, porque el dulce se disuelve en un menor tiempo en el agua que en las otras sustancias.', 'verdadera, porque el tiempo que tarde en disolverse depende del tamaño del dulce empleado.', 'falsa, porque el dulce podría disolverse en un menor tiempo con una mezcla de alcohol y aceite.'],
  'Compara la hipótesis palabra por palabra con lo que dice la tabla. Basta con que falle una parte.', 'publicada', 'modelo', '706fcc5f63258129d5e7c119672b52a2', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('ade731f1-e116-4aa5-95f6-16d7257b5459', 1, 'La hipótesis decía que el dulce se disolvería por completo en las tres sustancias y en el mismo tiempo. La tabla la desmiente: pasado ese tiempo solo el agua lo disolvió del todo, el alcohol apenas un poco y el aceite nada. Así que es falsa, y lo es por lo que se midió: el agua fue mucho más rápida que las otras dos. La opción que la da por verdadera contradice la tabla, y la que habla de mezclar alcohol y aceite propone un experimento que nunca se hizo.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '450f6d9a-cbff-4e39-b571-7ad3878ee700', 'qui',
  (select id from public.temas where materia = 'qui' and codigo = 'clasificacion-de-la-materia'),
  (select id from public.lotes where codigo = '2026-B'),
  'd25b0179-8817-4b93-a1d9-7a380257375f', 'Materia: clasificación y propiedades',
  'En la gráfica Presión - Temperatura, teniendo en cuenta el sentido de las flechas, la que mejor representa un proceso donde ocurre condensación y solidificación sería',
  array['4', '2', '1', '3'],
  'Dibuja con el dedo el camino que pide el enunciado —gas, líquido, sólido— y busca la flecha que atraviesa las tres regiones en ese orden.', 'publicada', 'modelo', 'a8d6dd4ca41c430cbe21e7b7a3166159', 'alta';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('450f6d9a-cbff-4e39-b571-7ad3878ee700', 1, 'Se piden dos cambios seguidos y en ese orden: primero de gas a líquido y después de líquido a sólido. En el dibujo eso significa una flecha que arranque en la región del gas y termine en la del sólido, cruzando por el medio la del líquido. La única que hace ese recorrido completo es la que sube hacia la izquierda: subir es ganar presión y moverse a la izquierda es perder temperatura. La que apunta hacia abajo pierde presión y va del sólido al gas, la de la parte baja pasa de gas a sólido de un solo salto, sin pasar por líquido, y la que apunta a la derecha calienta el gas sin cambiarlo de estado.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '21d956d7-36df-4c7c-aad3-e4d9d1e8846a', 'qui',
  (select id from public.temas where materia = 'qui' and codigo = 'clasificacion-de-la-materia'),
  (select id from public.lotes where codigo = '2026-B'),
  '6c4fbab5-3323-4b88-918f-1ae6a33ce273', 'Materia: clasificación y propiedades',
  'En el proceso de sublimación del hielo seco se observa la formación de una nube densa a los alrededores del bloque de hielo seco. Si se sabe que el CO<sub>2</sub> es incoloro y la temperatura del hielo seco es de −75 °C, es muy probable que la formación de esta nube corresponda al',
  array['dióxido de carbono que está pasando de estado sólido a estado gaseoso.', 'vapor de agua del ambiente que está pasando a estado líquido debido al intenso frío.', 'dióxido de carbono que está pasando de estado sólido a estado líquido.', 'agua del ambiente que está pasando a estado gaseoso debido al intenso frío.'],
  'Si un gas es incoloro, no puede ser lo que estás viendo. Pregúntate qué otra sustancia hay alrededor del bloque.', 'publicada', 'modelo', '4bafe47f646a1f0c8077d66ca142d7c5', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('21d956d7-36df-4c7c-aad3-e4d9d1e8846a', 1, 'El propio enunciado da la pista que resuelve la pregunta: el dióxido de carbono es incoloro, así que por mucho que se sublime no se puede ver. Lo que sí se ve es agua. A 75 grados bajo cero, el vapor de agua que hay en el aire alrededor del bloque se enfría de golpe y se condensa en gotitas diminutas, y esas gotitas son la nube blanca. Y no puede ser CO2 pasando a líquido, porque el enunciado dice que el hielo seco pasa directo de sólido a gas.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '0bdaa2ea-5beb-4057-9501-fd3df4f1e5fc', 'qui',
  (select id from public.temas where materia = 'qui' and codigo = 'soluciones'),
  (select id from public.lotes where codigo = '2026-B'),
  '51014855-c888-46aa-9aa8-8fd7abb0beac', 'Soluciones',
  'De acuerdo con la información anterior, es correcto afirmar que la muestra más contaminada es la',
  array['3', '4', '1', '2'],
  'Divide la masa entre el volumen en cada fila. Comparar solo la columna de masa favorece a la muestra más grande.', 'publicada', 'modelo', '822180170f350f099b3ded1d02f6598b', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('0bdaa2ea-5beb-4057-9501-fd3df4f1e5fc', 0, 'La muestra más contaminada no es la que tiene más plomo, sino la que tiene más plomo por cada litro de agua: si no, ganaría siempre la muestra más grande. Hay que dividir. La 1 da 2,5 entre 50, que son 0,05 miligramos por litro; la 2, 5 entre 100, otra vez 0,05; la 4, 50 entre 1.000, de nuevo 0,05. La 3 da 15 entre 200, que son 0,075: es la única que se sale del grupo, y hacia arriba.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select 'ec493cc9-07ae-49f9-80b9-d113d872898c', 'qui',
  (select id from public.temas where materia = 'qui' and codigo = 'nomenclatura-quimica'),
  (select id from public.lotes where codigo = '2026-B'),
  'ed85a062-e049-464a-a216-dcd6185e0adb', 'Nomenclatura química',
  'De acuerdo con la información anterior, se puede afirmar que las sustancias X y D son, respectivamente, un',
  array['no metal y una sal.', 'metal y una sal.', 'metal y un ácido.', 'no metal y una base.'],
  'El pH del producto intermedio te dice si X es metal o no metal. La reacción que libera agua te dice qué tipo de sustancia es D.', 'publicada', 'modelo', '26e096f76cba25aa429e69f95d53524d', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('ec493cc9-07ae-49f9-80b9-d113d872898c', 1, 'La pista está en el pH. El producto de la segunda reacción, el hidróxido X(OH)2, da por encima de 7, o sea que es una base, y los óxidos que al juntarse con agua forman bases son los de los metales: los de los no metales forman ácidos. Así que X es un metal. La tercera reacción toma esa base, la hace reaccionar con otra sustancia y devuelve agua más D: eso es una neutralización, y lo que sale junto al agua en una neutralización es una sal.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '3b4b5db8-23a8-49be-afea-f89284b48c1c', 'qui',
  (select id from public.temas where materia = 'qui' and codigo = 'clasificacion-de-la-materia'),
  (select id from public.lotes where codigo = '2026-B'),
  '17e15e4b-1a45-4de7-9162-6bc1c3591bad', 'Materia: clasificación y propiedades',
  'El componente L puede ser',
  array['arena.', 'hierro.', 'aceite.', 'sal.'],
  'Lee la fila de L como una lista de requisitos y descarta cualquier sustancia que incumpla uno solo.', 'publicada', 'modelo', 'd5ece375de7e40945faa5e1c78dd7163', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('3b4b5db8-23a8-49be-afea-f89284b48c1c', 2, 'La tabla dice tres cosas de L: es líquido, no se disuelve en agua y su densidad es 0,6, menor que la del agua. La arena y el hierro quedan fuera de entrada porque son sólidos, y la sal también, además de que se disuelve. El aceite cumple las tres: es líquido, no se mezcla con el agua y flota sobre ella justamente porque es menos denso.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '5c3afc39-33ad-4f49-be0c-530c6c2a9c04', 'qui',
  (select id from public.temas where materia = 'qui' and codigo = 'clasificacion-de-la-materia'),
  (select id from public.lotes where codigo = '2026-B'),
  '17e15e4b-1a45-4de7-9162-6bc1c3591bad', 'Materia: clasificación y propiedades',
  'El componente F se separa por los métodos 2 y 3, debido a que en dichos métodos se separan los materiales que tienen diferente',
  array['punto de ebullición.', 'tamaño de las partículas.', 'densidad.', 'solubilidad.'],
  'Piensa qué tienen en común un filtro y un colador: los dos clasifican por lo mismo.', 'publicada', 'modelo', '159cd67b6063988b421b345092e5b474', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('5c3afc39-33ad-4f49-be0c-530c6c2a9c04', 1, 'Los métodos 2 y 3 son la filtración y el tamizado, y los dos hacen lo mismo con distintos nombres: dejan pasar lo que es más pequeño que los agujeros y retienen lo que no cabe. Lo que decide en ambos casos es el tamaño de las partículas. La densidad es lo que separa la decantación, el punto de ebullición lo que separa la destilación, y la solubilidad no interviene aquí porque el propio enunciado dice que F es insoluble en agua.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select 'df940adf-208f-4fc9-bcbd-aa2b6a68ffc4', 'qui',
  (select id from public.temas where materia = 'qui' and codigo = 'clasificacion-de-la-materia'),
  (select id from public.lotes where codigo = '2026-B'),
  '11e80ef1-4c72-4515-9033-a67d219bb351', 'Materia: clasificación y propiedades',
  'De acuerdo con esto, el montaje más adecuado para la separación es',
  array['el de filtración.', 'el de evaporación.', 'el de destilación.', 'el de decantación.'],
  'Pregúntate qué propiedad es la única que distingue a los tres líquidos, y qué montaje la aprovecha.', 'publicada', 'modelo', '5ecd0cf31e54bc66aa71099de730d370', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('df940adf-208f-4fc9-bcbd-aa2b6a68ffc4', 2, 'Los tres líquidos se mezclan entre sí, así que no hay capas que separar ni sólidos que retener: filtrar o decantar no serviría de nada. Lo único distinto que ofrece la tabla son los puntos de ebullición, bastante separados: 40, 53,1 y 82,3 grados. Calentando poco a poco hierve primero el de 40, después el de 53,1 y por último el de 82,3, y cada vapor se recoge aparte al volverse líquido en el refrigerante. Eso es una destilación. La evaporación tampoco sirve, porque deja escapar el vapor en vez de recuperarlo.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select 'e8b1b116-c76d-4814-8311-1346ba8c215e', 'qui',
  (select id from public.temas where materia = 'qui' and codigo = 'clasificacion-de-la-materia'),
  (select id from public.lotes where codigo = '2026-B'),
  '7a7c4d09-f324-4824-bbc7-5a1fd6ef2db2', 'Materia: clasificación y propiedades',
  'De las estructuras anteriores, es válido afirmar que',
  array['R y J son compuestos y T es un elemento.', 'R y T son elementos y J es un compuesto.', 'J y T son compuestos y R es un elemento.', 'R y T son compuestos y J es un elemento.'],
  'No cuentes átomos, cuenta elementos distintos. Tres átomos del mismo elemento siguen siendo un solo elemento.', 'publicada', 'modelo', 'cf15dd85cbf5c4fec5f8ea550c1e5b2d', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('e8b1b116-c76d-4814-8311-1346ba8c215e', 3, 'La regla es contar cuántos elementos distintos aparecen en cada fórmula. R tiene carbono e hidrógeno, dos elementos: es un compuesto. T tiene carbono y oxígeno, también dos: compuesto. J está hecha solo de oxígeno, un único elemento, por muchos átomos que tenga: es una sustancia simple, no un compuesto. Que una fórmula tenga varios átomos no la convierte en compuesto; lo que cuenta es que sean de elementos diferentes.');

